import React, { useState } from 'react';

const ChampionsLeagueHeader = ({ players, onTeamsClick, onSeasonsClick }) => {
  const [selectedPlayer, setSelectedPlayer] = useState(null);
  const [showDropdown, setShowDropdown] = useState(null);

  const handlePlayerSelect = (player) => {
    setSelectedPlayer(player);
    setShowDropdown(null);
    if (showDropdown === 'teams') {
      onTeamsClick(player);
    } else if (showDropdown === 'seasons') {
      onSeasonsClick(player);
    }
  };

  const toggleDropdown = (type) => {
    if (showDropdown === type) {
      setShowDropdown(null);
    } else {
      setShowDropdown(type);
      setSelectedPlayer(null);
    }
  };

  return (
    <header className="bg-champions-blue p-4 flex justify-between items-center shadow-md relative">
      {/* Logo y título principal */}
      <div className="flex items-center">
        <div className="w-16 h-16 mr-2 overflow-hidden rounded-lg shadow-lg border border-champions-gold/30">
          <img 
            src="/images/logos/cc.png" 
            alt="Champions League Logo" 
            className="w-full h-full object-contain transform hover:scale-105 transition-transform duration-300"
          />
        </div>
        <div className="ml-4">
          <h2 className="text-white font-bold text-xl">UEFA Champions League</h2>
          <p className="text-blue-300 text-sm">Estadísticas Históricas</p>
        </div>
      </div>

      {/* Navegación */}
      <nav className="hidden md:flex space-x-6">
        <a href="#" className="text-white hover:text-champions-gold transition-colors">
          Inicio
        </a>
        <div className="relative">
          <a 
            href="#" 
            className={`text-white hover:text-champions-gold transition-colors flex items-center ${showDropdown === 'teams' ? 'text-champions-gold' : ''}`}
            onClick={(e) => {
              e.preventDefault();
              toggleDropdown('teams');
            }}
          >
            Equipos
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 ml-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
            </svg>
          </a>
          {showDropdown === 'teams' && (
            <div className="absolute z-10 mt-2 w-56 bg-white rounded-md shadow-lg">
              <div className="py-1 max-h-60 overflow-y-auto">
                <div className="px-4 py-2 text-xs font-medium text-gray-500 border-b">Selecciona un jugador</div>
                {players.map((player) => (
                  <a
                    key={player.position}
                    href="#"
                    className="block px-4 py-2 text-sm text-gray-700 hover:bg-blue-50 hover:text-champions-blue flex items-center"
                    onClick={(e) => {
                      e.preventDefault();
                      handlePlayerSelect(player);
                    }}
                  >
                    <span className="mr-2">{player.position}.</span> {player.name}
                  </a>
                ))}
              </div>
            </div>
          )}
        </div>
        <a href="#" className="text-white hover:text-champions-gold transition-colors">
          Jugadores
        </a>
        <div className="relative">
          <a 
            href="#" 
            className={`text-white hover:text-champions-gold transition-colors flex items-center ${showDropdown === 'seasons' ? 'text-champions-gold' : ''}`}
            onClick={(e) => {
              e.preventDefault();
              toggleDropdown('seasons');
            }}
          >
            Temporadas
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 ml-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
            </svg>
          </a>
          {showDropdown === 'seasons' && (
            <div className="absolute right-0 z-10 mt-2 w-56 bg-white rounded-md shadow-lg">
              <div className="py-1 max-h-60 overflow-y-auto">
                <div className="px-4 py-2 text-xs font-medium text-gray-500 border-b">Selecciona un jugador</div>
                {players.map((player) => (
                  <a
                    key={player.position}
                    href="#"
                    className="block px-4 py-2 text-sm text-gray-700 hover:bg-blue-50 hover:text-champions-blue flex items-center"
                    onClick={(e) => {
                      e.preventDefault();
                      handlePlayerSelect(player);
                    }}
                  >
                    <span className="mr-2">{player.position}.</span> {player.name}
                  </a>
                ))}
              </div>
            </div>
          )}
        </div>
      </nav>

      {/* Trofeo decorativo */}
      <div className="hidden md:flex items-center">
        <div className="w-16 h-16 overflow-hidden">
          <img 
            src="/images/trophy.png" 
            alt="Champions Trophy" 
            className="w-full h-full object-contain animate-pulse"
          />
        </div>
      </div>
    </header>
  );
};

export default ChampionsLeagueHeader;
